const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '入射光线' },
      { kind: 'text', payload: '法线' },
      { kind: 'text', payload: '反射光线' },
      { kind: 'text', payload: '反射角' }
    ];
  },
  render: function (input, metrics) {
    var vw = input.viewport.widthDu;
    var vh = input.viewport.heightDu;
    var DW = 640;
    var DH = 420;
    var s = Math.min(vw / DW, vh / DH);
    if (!isFinite(s) || s <= 0) { s = 1; }
    var ox = (vw - DW * s) / 2;
    var oy = (vh - DH * s) / 2;
    function X(x) { return ox + x * s; }
    function Y(y) { return oy + y * s; }

    var COLOR = '#1F3A5F';
    var MIRROR = '#33475B';

    var O = [320, 330];
    var A = [143, 153];
    var B = [497, 153];

    function seg(a, b) {
      return [['M', X(a[0]), Y(a[1])], ['L', X(b[0]), Y(b[1])]];
    }

    var mirrorCmds = seg([40, 330], [600, 330]);

    var hatchCmds = [];
    for (var hx = 60; hx <= 580; hx += 40) {
      var hs = seg([hx, 330], [hx - 14, 344]);
      hatchCmds.push(hs[0]);
      hatchCmds.push(hs[1]);
    }

    var normalCmds = [];
    for (var ny = 330; ny > 85; ny -= 17) {
      var nyTop = ny - 10;
      if (nyTop < 85) { nyTop = 85; }
      normalCmds.push(['M', X(320), Y(ny)]);
      normalCmds.push(['L', X(320), Y(nyTop)]);
      if (nyTop <= 85) { break; }
    }

    function arrowCmds(a, b, size) {
      var ax = X(a[0]);
      var ay = Y(a[1]);
      var bx = X(b[0]);
      var by = Y(b[1]);
      var dx = bx - ax;
      var dy = by - ay;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (!(len > 0)) { len = 1; dx = 1; dy = 0; }
      var ux = dx / len;
      var uy = dy / len;
      var S = size * s;
      var hx2 = bx - ux * S;
      var hy2 = by - uy * S;
      var px = -uy;
      var py = ux;
      var w = S * 0.4;
      return [
        ['M', ax, ay], ['L', bx, by],
        ['M', bx, by],
        ['L', hx2 + px * w, hy2 + py * w],
        ['L', hx2 - px * w, hy2 - py * w],
        ['Z']
      ];
    }

    function arcBand(cx, cy, r, a0, a1, halfW, n) {
      var cmds = [];
      var i, t, rr, px2, py2;
      rr = r + halfW;
      for (i = 0; i <= n; i++) {
        t = a0 + (a1 - a0) * i / n;
        px2 = X(cx + rr * Math.cos(t));
        py2 = Y(cy + rr * Math.sin(t));
        cmds.push(i === 0 ? ['M', px2, py2] : ['L', px2, py2]);
      }
      rr = r - halfW;
      for (i = n; i >= 0; i--) {
        t = a0 + (a1 - a0) * i / n;
        cmds.push(['L', X(cx + rr * Math.cos(t)), Y(cy + rr * Math.sin(t))]);
      }
      cmds.push(['Z']);
      return cmds;
    }

    var incidentCmds = arrowCmds(A, O, 15);
    var reflectedCmds = arrowCmds(O, B, 15);
    var arcCmds = arcBand(320, 330, 55, -Math.PI / 2, -Math.PI / 4, 1.2, 20);
    var dotCmds = visualSdk.circle(X(320), Y(330), Math.max(2, 3.2 * s));

    var wMain = Math.max(1.2, 2.2 * s);
    var wThin = Math.max(0.8, 1.4 * s);

    return {
      schemaVersion: 1,
      sceneId: 'reflection-figure',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: vw, height: vh },
      paths: [
        { id: 'mirror', commands: mirrorCmds },
        { id: 'hatch', commands: hatchCmds },
        { id: 'normal', commands: normalCmds },
        { id: 'incident', commands: incidentCmds },
        { id: 'reflected', commands: reflectedCmds },
        { id: 'angleArc', commands: arcCmds },
        { id: 'pointO', commands: dotCmds }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'mirror', fill: MIRROR, stroke: { width: wMain } },
          { type: 'path', pathId: 'hatch', fill: MIRROR, stroke: { width: wThin } },
          { type: 'path', pathId: 'normal', fill: COLOR, stroke: { width: wThin } },
          { type: 'path', pathId: 'incident', fill: COLOR, stroke: { width: wMain } },
          { type: 'path', pathId: 'reflected', fill: COLOR, stroke: { width: wMain } },
          { type: 'path', pathId: 'angleArc', fill: COLOR, stroke: { width: wThin } },
          { type: 'path', pathId: 'pointO', fill: COLOR },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: X(185), y: Y(210) }, hAlign: 'right', vAlign: 'middle', color: COLOR },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: X(332), y: Y(110) }, hAlign: 'left', vAlign: 'middle', color: COLOR },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: X(455), y: Y(210) }, hAlign: 'left', vAlign: 'middle', color: COLOR },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: X(358), y: Y(238) }, hAlign: 'center', vAlign: 'middle', color: COLOR }
        ]
      }
    };
  }
};
